		waiter.response.Add(1)
		waiter.ready <- true
	}

	// Convert items to interface{} for return
	disposedItems := make([]interface{}, len(pq.items))
	for i, item := range pq.items {
		disposedItems[i] = item
	}

	pq.items = nil
	pq.waiters = nil
	pq.itemMap = nil

	return disposedItems
}

// NewPriorityQueue is the constructor for a priority queue.
func NewPriorityQueue(hint int, allowDuplicates bool) *PriorityQueue {
	return &PriorityQueue{
		items:           make(priorityItems, 0, hint),
		itemMap:         make(map[Item]struct{}, hint),
		allowDuplicates: allowDuplicates,
	}
}
